import fs from "node:fs";
import path from "node:path";
import ts from "typescript";
import { pluginDir } from "./config.js";
import { PluginGenError } from "./errors.js";

export function generatedHeader(plugin: string, specUrl: string): string {
  return `// Generated by plugingen from ${specUrl}.
// Do not edit. Add an operation to plugingen.json and run: pnpm plugingen generate ${plugin}
/* eslint-disable */
`;
}

/** The path a generated file has in the repository, for reading and for commits. */
export function generatedPath(plugin: string, fileName: string): string {
  return `plugin-architecture/packages/${plugin}/src/${fileName}`;
}

/**
 * Generated files hold text a vendor chose, so prove one can do nothing: compiled, it
 * must leave no JavaScript at all, and as types it must not reach outside itself. Doc
 * comments carry `format` and `default` values through, and this is what says none of
 * them got out of the comment, whatever the escaping upstream does.
 */
export function assertTypesOnly(source: string): void {
  const compiled = ts.transpileModule(source, {
    reportDiagnostics: true,
    compilerOptions: {
      module: ts.ModuleKind.ESNext,
      target: ts.ScriptTarget.ES2022,
      removeComments: true,
    },
  });
  if (compiled.diagnostics?.length) {
    throw new PluginGenError("unsafe", "The generated types do not parse");
  }
  if (compiled.outputText.trim() !== "export {};") {
    throw new PluginGenError("unsafe", "The generated types contain code");
  }
  const file = ts.createSourceFile("gen.ts", source, ts.ScriptTarget.Latest, true);
  if (
    file.referencedFiles.length > 0 ||
    file.typeReferenceDirectives.length > 0 ||
    file.libReferenceDirectives.length > 0
  ) {
    throw new PluginGenError("unsafe", "The generated types reference another file");
  }
  const walk = (node: ts.Node): void => {
    if (ts.isImportTypeNode(node) || ts.isImportDeclaration(node)) {
      throw new PluginGenError("unsafe", "The generated types import something");
    }
    ts.forEachChild(node, walk);
  };
  walk(file);
}

export function readCommitted(root: string, plugin: string, fileName: string): string | undefined {
  try {
    return fs.readFileSync(path.join(pluginDir(root, plugin), "src", fileName), "utf8");
  } catch {
    return undefined;
  }
}

/** Atomic, because a type check in another process may be reading this file. */
export function writeGenerated(root: string, plugin: string, fileName: string, text: string): void {
  const target = path.join(pluginDir(root, plugin), "src", fileName);
  const temporary = `${target}.${process.pid}.tmp`;
  fs.writeFileSync(temporary, text);
  fs.renameSync(temporary, target);
}
